#![allow(dead_code)]
use std::sync::{Arc, LazyLock};

use datafusion::arrow::array::{
    ArrayRef, DictionaryArray, Int32Array, Int64Array, StringViewArray, UInt32Array, UInt64Array, UInt8Array,
};
use datafusion::arrow::datatypes::{DataType, Field, Int32Type, Int64Type, Schema, UInt32Type, UInt8Type};
use datafusion::arrow::util::display::{ArrayFormatter, FormatOptions};
use datafusion::arrow::{array::LargeStringArray, array::StringArray, record_batch::RecordBatch};
use datafusion::common::ParamValues;
use datafusion::error::Result;
use datafusion::execution::context::SessionContext;
use datafusion::prelude::SessionConfig;
use datafusion_functions_json::register_all;

pub async fn create_context() -> Result<SessionContext> {
    let config = SessionConfig::new().set_str("datafusion.sql_parser.dialect", "postgres");
    let mut ctx = SessionContext::new_with_config(config);
    register_all(&mut ctx)?;
    Ok(ctx)
}

pub static DICT_TYPE: LazyLock<DataType> =
    LazyLock::new(|| DataType::Dictionary(Box::new(DataType::Int32), Box::new(DataType::Utf8)));
pub static LARGE_DICT_TYPE: LazyLock<DataType> =
    LazyLock::new(|| DataType::Dictionary(Box::new(DataType::Int32), Box::new(DataType::LargeUtf8)));

#[expect(clippy::too_many_lines)]
async fn create_test_table(json_data_type: &DataType) -> Result<SessionContext> {
    let ctx = create_context().await?;

    let test_data = [
        ("object_foo", r#" {"foo": "abc"} "#),
        ("object_foo_array", r#" {"foo": [1]} "#),
        ("object_foo_obj", r#" {"foo": {}} "#),
        ("object_foo_null", r#" {"foo": null} "#),
        ("object_bar", r#" {"bar": true} "#),
        ("list_foo", r#" ["foo"] "#),
        ("invalid_json", "is not json"),
    ];
    let json_values = test_data.iter().map(|(_, json)| *json);

    let json_array = match json_data_type {
        DataType::Utf8 => Arc::new(StringArray::from_iter_values(json_values)) as ArrayRef,
        DataType::LargeUtf8 => Arc::new(LargeStringArray::from_iter_values(json_values)),
        DataType::Utf8View => Arc::new(StringViewArray::from_iter_values(json_values)),
        DataType::Dictionary(key_type, _) if key_type.as_ref() != &DataType::Int32 => {
            panic!("Only Int32 dictionary encoding is supported for JSON data in these tests")
        }
        DataType::Dictionary(key_type, child)
            if key_type.as_ref() == &DataType::Int32 && child.as_ref() == &DataType::Utf8 =>
        {
            Arc::new(DictionaryArray::<Int32Type>::new(
                Int32Array::from_iter_values(0..(i32::try_from(json_values.len()).expect("fits in a i32"))),
                Arc::new(StringArray::from_iter_values(json_values)),
            ))
        }
        DataType::Dictionary(key_type, child)
            if key_type.as_ref() == &DataType::Int32 && child.as_ref() == &DataType::LargeUtf8 =>
        {
            Arc::new(DictionaryArray::<Int32Type>::new(
                Int32Array::from_iter_values(0..(i32::try_from(json_values.len()).expect("fits in a i32"))),
                Arc::new(LargeStringArray::from_iter_values(json_values)),
            ))
        }
        _ => panic!("Unsupported JSON data type: {json_data_type}"),
    };

    let test_batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("name", DataType::Utf8View, false),
            Field::new("json_data", json_data_type.clone(), false),
        ])),
        vec![
            Arc::new(StringViewArray::from(
                test_data.iter().map(|(name, _)| *name).collect::<Vec<_>>(),
            )),
            json_array,
        ],
    )?;
    ctx.register_batch("test", test_batch)?;

    let other_data = [
        (r#" {"foo": 42} "#, "foo", 0),
        (r#" {"foo": 42} "#, "bar", 1),
        (r" [42] ", "foo", 0),
        (r" [42] ", "bar", 1),
    ];
    let other_batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("json_data", DataType::Utf8, false),
            Field::new("str_key", DataType::Utf8, false),
            Field::new("int_key", DataType::Int64, false),
        ])),
        vec![
            Arc::new(StringArray::from(
                other_data.iter().map(|(json, _, _)| *json).collect::<Vec<_>>(),
            )),
            Arc::new(StringArray::from(
                other_data.iter().map(|(_, str_key, _)| *str_key).collect::<Vec<_>>(),
            )),
            Arc::new(Int64Array::from(
                other_data.iter().map(|(_, _, int_key)| *int_key).collect::<Vec<_>>(),
            )),
        ],
    )?;
    ctx.register_batch("other", other_batch)?;

    let more_nested = [
        (r#" {"foo": {"bar": [0]}} "#, "foo", "bar", 0),
        (r#" {"foo": {"bar": [1]}} "#, "foo", "spam", 0),
        (r#" {"foo": {"bar": null}} "#, "foo", "bar", 0),
    ];
    let more_nested_batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("json_data", DataType::Utf8, false),
            Field::new("str_key1", DataType::Utf8, false),
            Field::new(
                "str_key2",
                DataType::Dictionary(Box::new(DataType::Int32), Box::new(DataType::Utf8)),
                false,
            ),
            Field::new("int_key", DataType::Int64, false),
        ])),
        vec![
            Arc::new(StringArray::from(
                more_nested.iter().map(|(json, _, _, _)| *json).collect::<Vec<_>>(),
            )),
            Arc::new(StringArray::from(
                more_nested
                    .iter()
                    .map(|(_, str_key1, _, _)| *str_key1)
                    .collect::<Vec<_>>(),
            )),
            Arc::new(
                more_nested
                    .iter()
                    .map(|(_, _, str_key2, _)| *str_key2)
                    .collect::<DictionaryArray<Int32Type>>(),
            ),
            Arc::new(Int64Array::from(
                more_nested
                    .iter()
                    .map(|(_, _, _, int_key)| *int_key)
                    .collect::<Vec<_>>(),
            )),
        ],
    )?;
    ctx.register_batch("more_nested", more_nested_batch)?;

    let dict_data = [
        (r#" {"foo": {"bar": [0]}} "#, "foo", "bar", 0),
        (r#" {"bar": "snap"} "#, "foo", "spam", 0),
        (r#" {"spam": 1, "snap": 2} "#, "foo", "spam", 0),
        (r#" {"spam": 1, "snap": 2} "#, "foo", "snap", 0),
    ];
    let dict_batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new(
                "json_data",
                DataType::Dictionary(DataType::UInt32.into(), DataType::Utf8.into()),
                false,
            ),
            Field::new(
                "str_key1",
                DataType::Dictionary(DataType::UInt8.into(), DataType::LargeUtf8.into()),
                false,
            ),
            Field::new(
                "str_key2",
                DataType::Dictionary(DataType::UInt8.into(), DataType::Utf8View.into()),
                false,
            ),
            Field::new(
                "int_key",
                DataType::Dictionary(DataType::Int64.into(), DataType::UInt64.into()),
                false,
            ),
        ])),
        vec![
            Arc::new(DictionaryArray::<UInt32Type>::new(
                UInt32Array::from_iter_values(
                    dict_data
                        .iter()
                        .enumerate()
                        .map(|(id, _)| u32::try_from(id).expect("fits in a u32")),
                ),
                Arc::new(StringArray::from(
                    dict_data.iter().map(|(json, _, _, _)| *json).collect::<Vec<_>>(),
                )),
            )),
            Arc::new(DictionaryArray::<UInt8Type>::new(
                UInt8Array::from_iter_values(
                    dict_data
                        .iter()
                        .enumerate()
                        .map(|(id, _)| u8::try_from(id).expect("fits in a u8")),
                ),
                Arc::new(LargeStringArray::from(
                    dict_data
                        .iter()
                        .map(|(_, str_key1, _, _)| *str_key1)
                        .collect::<Vec<_>>(),
                )),
            )),
            Arc::new(DictionaryArray::<UInt8Type>::new(
                UInt8Array::from_iter_values(
                    dict_data
                        .iter()
                        .enumerate()
                        .map(|(id, _)| u8::try_from(id).expect("fits in a u8")),
                ),
                Arc::new(StringViewArray::from(
                    dict_data
                        .iter()
                        .map(|(_, _, str_key2, _)| *str_key2)
                        .collect::<Vec<_>>(),
                )),
            )),
            Arc::new(DictionaryArray::<Int64Type>::new(
                Int64Array::from_iter_values(
                    dict_data
                        .iter()
                        .enumerate()
                        .map(|(id, _)| i64::try_from(id).expect("fits in a i64")),
                ),
                Arc::new(UInt64Array::from_iter_values(
                    dict_data
                        .iter()
                        .map(|(_, _, _, int_key)| u64::try_from(*int_key).expect("not negative")),
                )),
            )),
        ],
    )?;
    ctx.register_batch("dicts", dict_batch)?;

    Ok(ctx)
}

pub async fn run_query(sql: &str) -> Result<Vec<RecordBatch>> {
    run_query_datatype(sql, &DataType::Utf8View).await
}

pub async fn run_query_datatype(sql: &str, json_data_type: &DataType) -> Result<Vec<RecordBatch>> {
    let ctx = create_test_table(json_data_type).await?;
    ctx.sql(sql).await?.collect().await
}

pub async fn run_query_params(
    sql: &str,
    json_data_type: &DataType,
    query_values: impl Into<ParamValues>,
) -> Result<Vec<RecordBatch>> {
    let ctx = create_test_table(json_data_type).await?;
    ctx.sql(sql).await?.with_param_values(query_values)?.collect().await
}

pub async fn for_all_json_datatypes(f: impl AsyncFn(&DataType)) {
    for dt in [
        &DataType::Utf8,
        &DataType::LargeUtf8,
        &DataType::Utf8View,
        &DICT_TYPE,
        &LARGE_DICT_TYPE,
    ] {
        f(dt).await;
    }
}

pub async fn display_val(batch: Vec<RecordBatch>) -> (DataType, String) {
    assert_eq!(batch.len(), 1);
    let batch = batch.first().unwrap();
    assert_eq!(batch.num_rows(), 1);
    let schema = batch.schema();
    let schema_col = schema.field(0);
    let c = batch.column(0);
    let options = FormatOptions::default().with_display_error(true);
    let f = ArrayFormatter::try_new(c.as_ref(), &options).unwrap();
    let repr = f.value(0).try_to_string().unwrap();
    (schema_col.data_type().clone(), repr)
}

pub async fn logical_plan(sql: &str) -> Vec<String> {
    let batches = run_query(sql).await.unwrap();
    let plan_col = batches[0].column(1).as_any().downcast_ref::<StringArray>().unwrap();
    let logical_plan = plan_col.value(0);
    logical_plan.split('\n').map(ToString::to_string).collect()
}

/// Creates external API `ScalarUDF` for an array UDF. Specifically, creates
///
/// Creates a singleton `ScalarUDF` of the `$udf_impl` function named `$expr_fn_name _udf` and a
/// function named `$expr_fn_name _udf` which returns that function.
///
/// This is used to ensure creating the list of `ScalarUDF` only happens once.
///
/// # Arguments
/// * `udf_impl`: name of the [`ScalarUDFImpl`]
/// * `expr_fn_name`: name of the `expr_fn` function to be created
/// * `arg`: 0 or more named arguments for the function
/// * `doc`: documentation string for the function
///
/// Copied mostly from, `/datafusion/functions-array/src/macros.rs`.
///
/// [`ScalarUDFImpl`]: datafusion_expr::ScalarUDFImpl
macro_rules! make_udf_function {
    ($udf_impl:ty, $expr_fn_name:ident, $($arg:ident)*, $doc:expr) => {
        paste::paste! {
            #[doc = $doc]
            #[must_use] pub fn $expr_fn_name($($arg: datafusion::logical_expr::Expr),*) -> datafusion::logical_expr::Expr {
                datafusion::logical_expr::Expr::ScalarFunction(datafusion::logical_expr::expr::ScalarFunction::new_udf(
                    [< $expr_fn_name _udf >](),
                    vec![$($arg),*],
                ))
            }

            /// Singleton instance of [`$udf_impl`], ensures the UDF is only created once
            /// named for example `STATIC_JSON_OBJ_CONTAINS`
            static [< STATIC_ $expr_fn_name:upper >]: std::sync::OnceLock<std::sync::Arc<datafusion::logical_expr::ScalarUDF>> =
                std::sync::OnceLock::new();

            /// `ScalarFunction` that returns a [`ScalarUDF`] for [`$udf_impl`]
            ///
            /// [`ScalarUDF`]: datafusion::logical_expr::ScalarUDF
            pub fn [< $expr_fn_name _udf >]() -> std::sync::Arc<datafusion::logical_expr::ScalarUDF> {
                [< STATIC_ $expr_fn_name:upper >]
                    .get_or_init(|| {
                        std::sync::Arc::new(datafusion::logical_expr::ScalarUDF::new_from_impl(
                            <$udf_impl>::default(),
                        ))
                    })
                    .clone()
            }
        }
    };
}

pub(crate) use make_udf_function;

use std::any::Any;

use datafusion::arrow::array::BooleanArray;
use datafusion::arrow::datatypes::DataType;
use datafusion::common::Result as DataFusionResult;
use datafusion::logical_expr::{ColumnarValue, ScalarFunctionArgs, ScalarUDFImpl, Signature, Volatility};
use jiter::Peek;

use crate::common::{get_err, invoke, jiter_json_find, return_type_check, GetError, JsonPath};
use crate::common_macros::make_udf_function;

make_udf_function!(
    JsonGetBool,
    json_get_bool,
    json_data path,
    r#"Get an boolean value from a JSON string by its "path""#
);

#[derive(Debug, PartialEq, Eq, Hash)]
pub(super) struct JsonGetBool {
    signature: Signature,
    aliases: [String; 1],
}

impl Default for JsonGetBool {
    fn default() -> Self {
        Self {
            signature: Signature::variadic_any(Volatility::Immutable),
            aliases: ["json_get_bool".to_string()],
        }
    }
}

impl ScalarUDFImpl for JsonGetBool {
    fn as_any(&self) -> &dyn Any {
        self
    }

    fn name(&self) -> &str {
        self.aliases[0].as_str()
    }

    fn signature(&self) -> &Signature {
        &self.signature
    }

    fn return_type(&self, arg_types: &[DataType]) -> DataFusionResult<DataType> {
        return_type_check(arg_types, self.name(), DataType::Boolean).map(|_| DataType::Boolean)
    }

    fn invoke_with_args(&self, args: ScalarFunctionArgs) -> DataFusionResult<ColumnarValue> {
        invoke::<BooleanArray>(&args.args, jiter_json_get_bool)
    }

    fn aliases(&self) -> &[String] {
        &self.aliases
    }
}

fn jiter_json_get_bool(json_data: Option<&str>, path: &[JsonPath]) -> Result<bool, GetError> {
    if let Some((mut jiter, peek)) = jiter_json_find(json_data, path) {
        match peek {
            Peek::True | Peek::False => Ok(jiter.known_bool(peek)?),
            _ => get_err!(),
        }
    } else {
        get_err!()
    }
}

use std::any::Any;
use std::sync::Arc;

use datafusion::arrow::array::{ArrayRef, StringArray, StringBuilder};
use datafusion::arrow::datatypes::DataType;
use datafusion::common::{Result as DataFusionResult, ScalarValue};
use datafusion::logical_expr::{ColumnarValue, ScalarFunctionArgs, ScalarUDFImpl, Signature, Volatility};
use jiter::Peek;

use crate::common::{get_err, invoke, jiter_json_find, return_type_check, GetError, InvokeResult, JsonPath};
use crate::common_macros::make_udf_function;

make_udf_function!(
    JsonAsText,
    json_as_text,
    json_data path,
    r#"Get any value from a JSON string by its "path", represented as a string"#
);

#[derive(Debug, PartialEq, Eq, Hash)]
pub(super) struct JsonAsText {
    signature: Signature,
    aliases: [String; 1],
}

impl Default for JsonAsText {
    fn default() -> Self {
        Self {
            signature: Signature::variadic_any(Volatility::Immutable),
            aliases: ["json_as_text".to_string()],
        }
    }
}

impl ScalarUDFImpl for JsonAsText {
    fn as_any(&self) -> &dyn Any {
        self
    }

    fn name(&self) -> &str {
        self.aliases[0].as_str()
    }

    fn signature(&self) -> &Signature {
        &self.signature
    }

    fn return_type(&self, arg_types: &[DataType]) -> DataFusionResult<DataType> {
        return_type_check(arg_types, self.name(), DataType::Utf8)
    }

    fn invoke_with_args(&self, args: ScalarFunctionArgs) -> DataFusionResult<ColumnarValue> {
        invoke::<StringArray>(&args.args, jiter_json_as_text)
    }

    fn aliases(&self) -> &[String] {
        &self.aliases
    }
}

impl InvokeResult for StringArray {
    type Item = String;

    type Builder = StringBuilder;

    const ACCEPT_DICT_RETURN: bool = true;

    fn builder(capacity: usize) -> Self::Builder {
        StringBuilder::with_capacity(capacity, 0)
    }

    fn append_value(builder: &mut Self::Builder, value: Option<Self::Item>) {
        builder.append_option(value);
    }

    fn finish(mut builder: Self::Builder) -> DataFusionResult<ArrayRef> {
        Ok(Arc::new(builder.finish()))
    }

    fn scalar(value: Option<Self::Item>) -> ScalarValue {
        ScalarValue::Utf8(value)
    }
}

fn jiter_json_as_text(opt_json: Option<&str>, path: &[JsonPath]) -> Result<String, GetError> {
    if let Some((mut jiter, peek)) = jiter_json_find(opt_json, path) {
        match peek {
            Peek::Null => {
                jiter.known_null()?;
                get_err!()
            }
            Peek::String => Ok(jiter.known_str()?.to_owned()),
            _ => {
                let start = jiter.current_index();
                jiter.known_skip(peek)?;
                let object_slice = jiter.slice_to_current(start);
                let object_string = std::str::from_utf8(object_slice)?;
                Ok(object_string.to_owned())
            }
        }
    } else {
        get_err!()
    }
}

use std::any::Any;
use std::sync::Arc;

use datafusion::arrow::array::BooleanBuilder;
use datafusion::arrow::datatypes::DataType;
use datafusion::common::arrow::array::{ArrayRef, BooleanArray};
use datafusion::common::{plan_err, Result, ScalarValue};
use datafusion::logical_expr::{ColumnarValue, ScalarFunctionArgs, ScalarUDFImpl, Signature, Volatility};

use crate::common::{invoke, jiter_json_find, return_type_check, GetError, InvokeResult, JsonPath};
use crate::common_macros::make_udf_function;

make_udf_function!(
    JsonContains,
    json_contains,
    json_data path,
    r#"Does the key/index exist within the JSON value as the specified "path"?"#
);

#[derive(Debug, PartialEq, Eq, Hash)]
pub(super) struct JsonContains {
    signature: Signature,
    aliases: [String; 1],
}

impl Default for JsonContains {
    fn default() -> Self {
        Self {
            signature: Signature::variadic_any(Volatility::Immutable),
            aliases: ["json_contains".to_string()],
        }
    }
}

impl ScalarUDFImpl for JsonContains {
    fn as_any(&self) -> &dyn Any {
        self
    }

    fn name(&self) -> &str {
        self.aliases[0].as_str()
    }

    fn signature(&self) -> &Signature {
        &self.signature
    }

    fn return_type(&self, arg_types: &[DataType]) -> Result<DataType> {
        if arg_types.len() < 2 {
            plan_err!("The 'json_contains' function requires two or more arguments.")
        } else {
            return_type_check(arg_types, self.name(), DataType::Boolean).map(|_| DataType::Boolean)
        }
    }

    fn invoke_with_args(&self, args: ScalarFunctionArgs) -> Result<ColumnarValue> {
        invoke::<BooleanArray>(&args.args, jiter_json_contains)
    }

    fn aliases(&self) -> &[String] {
        &self.aliases
    }
}

impl InvokeResult for BooleanArray {
    type Item = bool;

    type Builder = BooleanBuilder;

    // Using boolean inside a dictionary is not an optimization!
    const ACCEPT_DICT_RETURN: bool = false;

    fn builder(capacity: usize) -> Self::Builder {
        BooleanBuilder::with_capacity(capacity)
    }

    fn append_value(builder: &mut Self::Builder, value: Option<Self::Item>) {
        builder.append_option(value);
    }

    fn finish(mut builder: Self::Builder) -> Result<ArrayRef> {
        Ok(Arc::new(builder.finish()))
    }

    fn scalar(value: Option<Self::Item>) -> ScalarValue {
        ScalarValue::Boolean(value)
    }
}

#[allow(clippy::unnecessary_wraps)]
fn jiter_json_contains(json_data: Option<&str>, path: &[JsonPath]) -> Result<bool, GetError> {
    Ok(jiter_json_find(json_data, path).is_some())
}

